import "./styles/skeuo-button.css";
import type { ButtonHTMLAttributes } from "react";

export type SkeuoButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: "default" | "primary";
  square?: boolean;
  size?: "sm" | "md" | "lg";
  loading?: boolean;
};

/** A raised control with a physical pressed state. */
export function SkeuoButton({ variant = "default", square = false, size = "md", loading = false, disabled, children, className = "", type = "button", ...props }: SkeuoButtonProps) {
  return <button data-sk-root="" type={type} disabled={disabled || loading} aria-busy={loading || undefined} data-size={size} className={`sk-button ${variant === "primary" ? "sk-primary" : ""} ${square ? "sk-square" : ""} ${className}`} {...props}>{loading && <span className="sk-spinner" aria-hidden="true" />}{children}</button>;
}

import "./styles/skeuo-surface.css";
import type { HTMLAttributes } from "react";
export function SkeuoSurface({ variant = "raised", className = "", ...props }: HTMLAttributes<HTMLDivElement> & { variant?: "raised" | "recessed" }) {
  return <div data-sk-root="" className={`sk-surface sk-surface-${variant} ${className}`} {...props} />;
}

"use client";
import "./styles/skeuo-switch.css";


import type { ButtonHTMLAttributes } from "react";

export type SkeuoSwitchProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> & {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
};

/** Controlled switch; provide an accessible label or aria-labelledby. */
export function SkeuoSwitch({ checked, onCheckedChange, className = "", onClick, ...props }: SkeuoSwitchProps) {
  return <button data-sk-root="" {...props} type="button" className={`sk-switch ${className}`} role="switch" aria-checked={checked} onClick={event => { onClick?.(event); if (!event.defaultPrevented) onCheckedChange(!checked); }}><span><i /><i /><i /></span></button>;
}

"use client";
import type { ButtonHTMLAttributes, ReactNode } from "react";
import { SkeuoIcon as Icon } from "./skeuo-icons";
import "./styles/skeuo-theme-button.css";
export type SkeuoThemeButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> & {
  theme: "light" | "dark";
  onThemeChange: (theme: "light" | "dark") => void;
  variant?: "key" | "round";
  lightIcon?: ReactNode;
  darkIcon?: ReactNode;
};
/** Controlled by the host app: no document mutations, storage, or theme-provider dependency. */
export function SkeuoThemeButton({ theme, onThemeChange, variant = "key", lightIcon, darkIcon, className = "", onClick, ...props }: SkeuoThemeButtonProps) {
  return <button {...props} data-sk-root="" type={props.type ?? "button"} className={`sk-theme-key ${variant === "round" ? "sk-is-round" : ""} ${className}`} aria-label={props["aria-label"] ?? `Switch to ${theme === "dark" ? "light" : "dark"} theme`} onClick={event => { onClick?.(event); if (!event.defaultPrevented) onThemeChange(theme === "dark" ? "light" : "dark"); }}>{theme === "dark" ? (lightIcon ?? <Icon name="sun" size={20} />) : (darkIcon ?? <Icon name="moon" size={20} />)}</button>;
}

