function A({
  href,
  className,
  label,
  children,
  style,
}: {
  href?: string;
  className?: string;
  label?: string;
  children: React.ReactNode;
  style?: React.CSSProperties;
}) {
  const onClick = (e: React.MouseEvent) => {
    if (!href || href === "#") e.preventDefault();
  };
  const out = !!href && /^https?:/.test(href);
  return (
    <a
      href={href || "#"}
      className={className}
      aria-label={label}
      title={label}
      onClick={onClick}
      style={style}
      {...(out ? { target: "_blank", rel: "noopener noreferrer" } : {})}
    >
      {children}
    </a>
  );
}

export default function PushpinTearFooter({
  brand = "kedhar.",
  name = "kedhareswer",
  logo,
  logoHref = HOME,
  socials = DEFAULT_SOCIALS,
  email = "hello@example.com",
  newsletter = {
    label: "new components, once a month",
    placeholder: "your@email",
  },
  status = { label: "open for collaborations" },
  mark = "KS / 2026",
  timeZone = "Asia/Kolkata",
  timeLabel = "IST",
  columns = DEFAULT_COLUMNS,
  chat = { label: "say hi" },
  sideLinks = DEFAULT_SIDES,
  copyright = "© 2026 Kedhareswer",
  credit = "designed & built by hand",
  handle = { label: "@" + ME, href: HOME },
  sheet = "#1a7ff0",
  paper = "#f3f3f1",
  sheetInk = "#ffffff",
  paperInk,
  seed = 7,
  height = "100svh",
  fontSans = '"Helvetica Neue", Helvetica, Arial, system-ui, sans-serif',
  onSubscribe,
  onRepin,
  className = "",
}: PushpinTearFooterProps) {
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  const rootRef = React.useRef<HTMLElement>(null);
  const svgRef = React.useRef<SVGSVGElement>(null);
  const sheetRef = React.useRef<SVGPathElement>(null);
  const rimRef = React.useRef<SVGPathElement>(null);
  const flapRefs = React.useRef<(SVGPathElement | null)[]>([]);
  const gradRefs = React.useRef<(SVGLinearGradientElement | null)[]>([]);
  const pinRef = React.useRef<HTMLButtonElement>(null);
  const timers = React.useRef<number[]>([]);

  const still = useReducedMotion();
  const [stage, setStage] = React.useState(0);
  const [hit, setHit] = React.useState(false);
  const [visible, setVisible] = React.useState(false);
  const [pin, setPin] = React.useState<"idle" | "lift" | "stab">("idle");
  const [sent, setSent] = React.useState(false);
  const [address, setAddress] = React.useState("");
  const [toast, setToast] = React.useState("");
  const [grain, setGrain] = React.useState("");

  const s = React.useRef({
    W: 0,
    H: 0,
    tear: makeTear(seed),
    prev: null as Tear | null,
    from: [] as number[],
    ys: [] as number[],
    mode: "wait" as "wait" | "intro" | "morph" | "rest",
    t0: 0,
    dur: 1,
    raf: 0,
    px: -1e4,
    py: -1e4,
    lift: new Array(FLAPS).fill(0) as number[],
    still: false,
    busy: false,
    seed,
  }).current;
  s.still = still;

  const later = (fn: () => void, ms: number) => {
    timers.current.push(window.setTimeout(fn, ms));
  };

  // ---- drawing --------------------------------------------------------------
  const frame = React.useCallback(
    (now: number) => {
      s.raf = 0;
      const { W, H, tear } = s;
      if (!W || !H) return;
      let busy = false;
      let ys: number[];
      const open = new Array(FLAPS).fill(1);
      const openOld = new Array(FLAPS).fill(0);
      if (s.mode === "wait") {
        ys = tear.ys.map(() => START);
        open.fill(0);
      } else if (s.mode === "intro") {
        const p = (now - s.t0) / s.dur;
        ys = introYs(tear, Math.min(1, p));
        tear.flaps.forEach(
          (f, k) => (open[k] = flapOpen(tear, f, Math.min(1, p))),
        );
        if (p >= 1) s.mode = "rest";
        else busy = true;
      } else if (s.mode === "morph") {
        const p = (now - s.t0) / s.dur;
        ys = morphYs(s.from, tear, Math.min(1, p));
        open.fill(easeTear((p - 0.5) / 0.5));
        openOld.fill(1 - easeInOut(p / 0.35));
        if (p >= 1) s.mode = "rest";
        else busy = true;
      } else ys = tear.ys;
      s.ys = ys;

      // flaps lift towards a nearby pointer
      tear.flaps.forEach((f, k) => {
        const b = Math.min(ys.length - 1, f.at + f.span);
        const mx = ((XS[f.at] + XS[b]) / 2) * W;
        const my = ((ys[f.at] + ys[b]) / 2) * H;
        const target = s.still
          ? 0
          : clamp01(
              1 - Math.hypot(s.px - mx, s.py - my) / (0.2 * Math.max(W, 520)),
            );
        s.lift[k] += (target - s.lift[k]) * 0.14;
        if (Math.abs(target - s.lift[k]) > 0.003) busy = true;
        open[k] *= 1 + 0.32 * s.lift[k];
      });

      sheetRef.current?.setAttribute("d", sheetD(ys, W, H, tear.rim));
      rimRef.current?.setAttribute("d", sheetD(ys, W, H));
      const draw = (k: number, f: Flap | undefined, o: number) => {
        const el = flapRefs.current[k];
        const g = gradRefs.current[k];
        if (!el || !g) return;
        if (!f || o < 0.01) return el.setAttribute("d", "");
        const pts = flapPoly(ys, f, W, H, o);
        el.setAttribute("d", polyD(pts));
        const b = Math.min(ys.length - 1, f.at + f.span);
        const tip = pts[f.span + 3];
        g.setAttribute("x1", String(((XS[f.at] + XS[b]) / 2) * W));
        g.setAttribute("y1", String(((ys[f.at] + ys[b]) / 2) * H));
        g.setAttribute("x2", String(tip[0]));
        g.setAttribute("y2", String(tip[1]));
      };
      for (let k = 0; k < FLAPS; k++) {
        draw(k, tear.flaps[k], open[k]);
        draw(FLAPS + k, s.prev?.flaps[k], openOld[k]);
      }
      if (busy) s.raf = requestAnimationFrame(frame);
    },
    [s],
  );

  const kick = React.useCallback(() => {
    if (!s.raf && typeof requestAnimationFrame !== "undefined")
      s.raf = requestAnimationFrame(frame);
  }, [s, frame]);

  // size
  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => {
      s.W = el.clientWidth;
      s.H = el.clientHeight;
      const svg = svgRef.current;
      if (svg) {
        svg.setAttribute("width", String(s.W));
        svg.setAttribute("height", String(s.H));
        svg.setAttribute("viewBox", "0 0 " + s.W + " " + s.H);
      }
      kick();
    });
    ro.observe(el);
    return () => {
      ro.disconnect();
      cancelAnimationFrame(s.raf);
      s.raf = 0;
    };
  }, [s, kick]);

  // visibility
  React.useEffect(() => {
    const el = rootRef.current;
    if (!el || typeof IntersectionObserver === "undefined")
      return setVisible(true);
    const io = new IntersectionObserver(([e]) => setVisible(e.isIntersecting), {
      threshold: 0.22,
    });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  // grain tile, once
  React.useEffect(() => {
    const c = document.createElement("canvas");
    c.width = c.height = 160;
    const g = c.getContext("2d");
    if (!g) return;
    const img = g.createImageData(160, 160);
    const r = rng(42);
    for (let i = 0; i < img.data.length; i += 4) {
      const v = r() < 0.5 ? 0 : 255;
      img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
      img.data[i + 3] = Math.floor(r() * 46);
    }
    g.putImageData(img, 0, 0);
    setGrain(c.toDataURL());
  }, []);

  // the opening: chrome, pin, rip
  React.useEffect(() => {
    if (!visible || stage > 0) return;
    if (still) {
      setStage(3);
      s.mode = "rest";
      kick();
      return;
    }
    setStage(1);
    later(() => setStage(2), 640);
    later(() => {
      setHit(true);
      setStage(3);
      s.mode = "intro";
      s.t0 = performance.now();
      s.dur = 1550;
      kick();
    }, 1140);
    later(() => setHit(false), 1480);
  }, [visible, stage, still, s, kick]);

  React.useEffect(
    () => () => {
      timers.current.forEach((id) => clearTimeout(id));
    },
    [],
  );

  // a new seed from outside re-tears in place
  React.useEffect(() => {
    if (seed === s.seed) return;
    s.seed = seed;
    s.prev = s.tear;
    s.from = s.ys.length ? s.ys : s.tear.ys;
    s.tear = makeTear(seed);
    if (s.mode !== "wait") {
      s.mode = still ? "rest" : "morph";
      s.t0 = performance.now();
      s.dur = 1100;
    }
    kick();
  }, [seed, still, s, kick]);

  // ---- actions ----------------------------------------------------------------
  const onPointerMove = (e: React.PointerEvent) => {
    const el = rootRef.current;
    if (!el || s.still) return;
    const r = el.getBoundingClientRect();
    s.px = e.clientX - r.left;
    s.py = e.clientY - r.top;
    const tilt = Math.max(-9, Math.min(9, (s.px / r.width - 0.5) * 18));
    pinRef.current?.style.setProperty("--tilt", tilt.toFixed(2) + "deg");
    kick();
  };
  const onPointerLeave = () => {
    s.px = s.py = -1e4;
    pinRef.current?.style.setProperty("--tilt", "0deg");
    kick();
  };

  const repin = () => {
    if (s.busy || stage < 3) return;
    const next = s.seed + 1;
    const swap = () => {
      s.seed = next;
      s.prev = s.tear;
      s.from = s.ys.length ? s.ys : s.tear.ys;
      s.tear = makeTear(next);
    };
    if (still) {
      swap();
      s.prev = null;
      s.mode = "rest";
      kick();
      onRepin?.(next);
      return;
    }
    s.busy = true;
    setPin("lift");
    later(() => {
      swap();
      s.mode = "morph";
      s.t0 = performance.now();
      s.dur = 1150;
      kick();
    }, 300);
    later(() => setPin("stab"), 1280);
    later(() => {
      setPin("idle");
      s.busy = false;
      onRepin?.(next);
    }, 1720);
  };

  const flash = (msg: string) => {
    setToast(msg);
    later(() => setToast(""), 1600);
  };
  const copyEmail = () => {
    if (!email) return;
    if (navigator.clipboard?.writeText)
      navigator.clipboard.writeText(email).then(
        () => flash("email copied"),
        () => flash(email),
      );
    else flash(email);
  };
  const toTop = () =>
    window.scrollTo({ top: 0, behavior: still ? "auto" : "smooth" });
  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    const v = address.trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) return flash("check that email");
    setSent(true);
    onSubscribe?.(v);
  };

  // ---- colours ----------------------------------------------------------------
  const pinBase = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(sheet)
    ? sheet
    : "#1a7ff0";
  // flaps are the back of the sheet: paper-white
  const flapBase = mixHex(
    /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(paper) ? paper : "#f3f3f1",
    "#ffffff",
    0.35,
  );
  const vars = {
    height: typeof height === "number" ? height + "px" : height,
    "--tpf-sheet": sheet,
    "--tpf-paper": paper,
    "--tpf-on-sheet": sheetInk,
    "--tpf-on-paper": paperInk ?? sheet,
    "--tpf-rim": mixHex(flapBase, "#ffffff", 0.6),
    "--tpf-sans": fontSans,
  } as React.CSSProperties;

  const mailto = email ? "mailto:" + email : "#";
  const cols = columns.slice(0, 2);
  const H = (i: number) => ({ "--i": i }) as React.CSSProperties;

  const cls = [
    "tpf",
    stage >= 1 && "s1",
    stage >= 2 && "s2",
    stage >= 3 && "s3",
    hit && "is-hit",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <footer
      ref={rootRef}
      className={cls}
      style={vars}
      onPointerMove={onPointerMove}
      onPointerLeave={onPointerLeave}
    >
      <style>{CSS}</style>

      <svg ref={svgRef} className="tpf-stage" aria-hidden="true">
        <defs>
          <radialGradient id={uid + "v"} cx=".5" cy=".78" r=".75">
            <stop offset=".45" stopColor="#fff" stopOpacity="0" />
            <stop offset="1" stopColor="#0d1c38" stopOpacity=".07" />
          </radialGradient>
          <linearGradient id={uid + "l"} x1="0" y1="0" x2=".35" y2="1">
            <stop offset="0" stopColor="#fff" stopOpacity=".13" />
            <stop offset=".55" stopColor="#fff" stopOpacity="0" />
            <stop offset="1" stopColor="#001033" stopOpacity=".12" />
          </linearGradient>
          {grain && (
            <pattern
              id={uid + "g"}
              width="160"
              height="160"
              patternUnits="userSpaceOnUse"
            >
              <image href={grain} width="160" height="160" />
            </pattern>
          )}
          <filter id={uid + "d"} x="-5%" y="-5%" width="110%" height="120%">
            <feDropShadow
              dx="0"
              dy="3"
              stdDeviation="3.5"
              floodColor="#0a1a3a"
              floodOpacity=".3"
            />
          </filter>
          <filter id={uid + "f"} x="-30%" y="-30%" width="160%" height="170%">
            <feDropShadow
              dx="-2"
              dy="4"
              stdDeviation="4"
              floodColor="#0a1a3a"
              floodOpacity=".26"
            />
          </filter>
          {Array.from({ length: FLAPS * 2 }, (_, k) => (
            <linearGradient
              key={k}
              id={uid + "fg" + k}
              ref={(el) => {
                gradRefs.current[k] = el;
              }}
              gradientUnits="userSpaceOnUse"
            >
              <stop offset="0" stopColor={mixHex(flapBase, "#1c2a44", 0.34)} />
              <stop offset=".5" stopColor={mixHex(flapBase, "#1c2a44", 0.08)} />
              <stop offset="1" stopColor="#ffffff" />
            </linearGradient>
          ))}
          <path id={uid + "s"} ref={sheetRef} />
        </defs>
        <rect className="tpf-paper" width="100%" height="100%" />
        <rect
          width="100%"
          height="100%"
          fill={"url(#" + uid + "v)"}
          style={{ mixBlendMode: "multiply" }}
        />
        {grain && (
          <rect
            width="100%"
            height="100%"
            fill={"url(#" + uid + "g)"}
            opacity=".32"
          />
        )}
        <g className="tpf-sheet-g" filter={"url(#" + uid + "d)"}>
          <path ref={rimRef} className="tpf-rim" />
          <use href={"#" + uid + "s"} className="tpf-sheet" />
        </g>
        <use href={"#" + uid + "s"} fill={"url(#" + uid + "l)"} />
        {grain && (
          <use
            href={"#" + uid + "s"}
            fill={"url(#" + uid + "g)"}
            opacity=".5"
          />
        )}
        <g filter={"url(#" + uid + "f)"}>
          {Array.from({ length: FLAPS * 2 }, (_, k) => (
            <path
              key={k}
              ref={(el) => {
                flapRefs.current[k] = el;
              }}
              fill={"url(#" + uid + "fg" + k + ")"}
            />
          ))}
        </g>
      </svg>

      {/* ---- on the sheet ---- */}
      <div className="tpf-z tpf-top">
        <div className="tpf-row tpf-h" style={H(0)}>
          <button
            type="button"
            className="tpf-ib tpf-up"
            onClick={toTop}
            aria-label="Back to top"
            title="Back to top"
          >
            <Icon name="chevL" />
          </button>
          <span style={{ width: ".6em" }} />
          {socials.map((l, i) => (
            <A key={i} href={l.href} className="tpf-ib" label={l.label}>
              <Icon name={l.icon} />
            </A>
          ))}
        </div>
        <A
          href={logoHref}
          className="tpf-logo tpf-h"
          label={name + ", home"}
          style={H(1)}
        >
          {logo ?? <KMark />}
        </A>
        {email && (
          <div className="tpf-h" style={{ ...H(2), position: "relative" }}>
            <button
              type="button"
              className="tpf-mail"
              onClick={copyEmail}
              aria-label={"Copy " + email}
              title="Copy email"
            >
              <span>{email}</span>
              <Icon name="copy" />
            </button>
            <span
              className={"tpf-toast" + (toast ? " on" : "")}
              role="status"
              aria-live="polite"
            >
              {toast}
            </span>
          </div>
        )}
      </div>

      {newsletter && (
        <form className="tpf-z tpf-news tpf-h" style={H(3)} onSubmit={submit}>
          <label htmlFor={uid + "e"}>{newsletter.label}</label>
          <div className="tpf-pill" data-sent={sent}>
            <input
              id={uid + "e"}
              type="email"
              placeholder={newsletter.placeholder ?? "your@email"}
              autoComplete="email"
              value={address}
              disabled={sent}
              onChange={(e) => setAddress(e.target.value)}
            />
            <span className="tpf-sent" aria-live="polite">
              {sent ? (
                <>
                  <Icon name="check" /> you&apos;re on the list
                </>
              ) : null}
            </span>
            <button
              type="submit"
              className="tpf-knob"
              aria-label="Subscribe"
              disabled={sent}
            >
              <Icon name={sent ? "check" : "arrow"} />
            </button>
          </div>
        </form>
      )}

      {mark && (
        <span
          className="tpf-z tpf-flank tpf-h"
          style={{ ...H(4), left: "24%" }}
        >
          {mark}
        </span>
      )}
      {timeZone && (
        <span
          className="tpf-z tpf-flank tpf-h"
          style={{ ...H(4), left: "76%" }}
          title={"Local time · " + timeZone}
        >
          <Clock zone={timeZone} label={timeLabel} />
        </span>
      )}

      {status && (
        <>
          <A
            href={status.href ?? mailto}
            className="tpf-z tpf-status tpf-h"
            style={H(5)}
          >
            <i className="tpf-live" aria-hidden="true" />
            <span>{status.label}</span>
          </A>
          <span className="tpf-z tpf-badge" aria-hidden="true">
            <span
              className="tpf-h"
              style={{
                ...H(6),
                display: "block",
                width: "100%",
                height: "100%",
              }}
            >
              <Seal />
            </span>
          </span>
        </>
      )}

      {cols.map((c, i) => (
        <nav
          key={i}
          className={"tpf-z tpf-col tpf-h " + (i ? "r" : "l")}
          style={H(6 + i)}
          aria-label={c.title}
        >
          <h3>
            {c.title}
            <Icon name="squiggle" />
          </h3>
          <ul>
            {c.links.map((l, j) => (
              <li key={j}>
                <A href={l.href}>{l.label}</A>
              </li>
            ))}
          </ul>
          {(() => {
            const cta = c.cta ?? (i ? { label: "talk.", href: mailto } : null);
            return cta ? (
              <A href={cta.href} className="tpf-big">
                {cta.label}
              </A>
            ) : null;
          })()}
        </nav>
      ))}

      {/* ---- the pin ---- */}
      <button
        ref={pinRef}
        type="button"
        className="tpf-pin"
        data-pin={pin}
        onClick={repin}
        aria-label="Re-pin: tear a new edge"
        title="Pull the pin"
      >
        <span className="tpf-shadow" aria-hidden="true" />
        <span className="tpf-tilt">
          <span className="tpf-drop">
            <span className="tpf-body">
              <Pin base={pinBase} id={uid + "p"} />
            </span>
          </span>
        </span>
      </button>

      {/* ---- printed on the paper ---- */}
      <div className="tpf-z tpf-brand tpf-ink">
        <div className="tpf-brand-top tpf-p" style={H(0)}>
          <span className="tpf-eye">{name}</span>
          {chat && (
            <A
              href={chat.href ?? mailto}
              className="tpf-bub"
              label={chat.label}
            >
              <span className="tpf-dots" aria-hidden="true">
                <i />
                <i />
                <i />
              </span>
              <b>{chat.label}</b>
            </A>
          )}
        </div>
        <A href={logoHref} className="tpf-word" label={name}>
          <span>{brand}</span>
        </A>
      </div>

      {sideLinks.slice(0, 2).map((l, i) => (
        <A
          key={i}
          href={l.href}
          className={"tpf-z tpf-side tpf-ink tpf-p " + (i ? "r" : "l")}
          label={l.label}
          style={{ ...H(1 + i), left: i ? "71.5%" : "29.5%" }}
        >
          <span>{l.label}</span>
          <Icon name={l.icon} />
        </A>
      ))}

      <div className="tpf-z tpf-foot tpf-ink">
        <span className="tpf-p" style={H(3)}>
          {copyright}
        </span>
        {credit && (
          <span className="tpf-credit tpf-p" style={H(4)}>
            {credit}
          </span>
        )}
        <A href={handle.href} className="tpf-handle tpf-p" style={H(5)}>
          {handle.label}
        </A>
      </div>
    </footer>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { TemplateMode, TemplatePalette } from "./theme-presets";
import { themePresets } from "./theme-presets";
import { SkeuoThemeButton } from "../skeuo-theme-button";

export function TemplateCustomizer({
  palette,
  mode,
  onPaletteChange,
  onModeChange,
  onReset,
  templatesHref = "#",
}: {
  templatesHref?: string;
  palette: TemplatePalette;
  mode: TemplateMode;
  onPaletteChange: (value: TemplatePalette) => void;
  onModeChange: (value: TemplateMode) => void;
  onReset: () => void;
}) {
  const [open, setOpen] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") setOpen(false);
    }
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [open]);

  return (
    <div ref={panelRef} className={`tpl-customizer ${open ? "is-open" : ""}`}>
      <button
        type="button"
        className="tpl-customizer-trigger"
        aria-label="Customize template"
        aria-expanded={open}
        aria-controls="tpl-customizer-panel"
        onClick={() => setOpen(!open)}
      >
        <span className="tpl-customizer-trigger-art" aria-hidden="true">
          <i />
          <i />
          <i />
        </span>
        <span>Customize</span>
        <span aria-hidden="true">{open ? "×" : "+"}</span>
      </button>
      <div
        id="tpl-customizer-panel"
        className="tpl-customizer-panel"
        hidden={!open}
      >
        <div className="tpl-customizer-heading">
          <div>
            <span>MAKE IT YOURS</span>
            <h2>Choose a world.</h2>
          </div>
          <button
            type="button"
            onClick={() => setOpen(false)}
            aria-label="Close customization"
          >
            ×
          </button>
        </div>
        <p>
          Each palette changes the canvas, surfaces, wells, typography, and
          accents together.
        </p>
        <div
          className="tpl-customizer-palettes"
          role="group"
          aria-label="Color palette"
        >
          {(Object.keys(themePresets) as TemplatePalette[]).map((key) => {
            const preset = themePresets[key];
            const colors = preset[mode];
            return (
              <button
                key={key}
                type="button"
                className="tpl-palette-option"
                aria-pressed={palette === key}
                onClick={() => onPaletteChange(key)}
              >
                <span
                  className="tpl-palette-specimen"
                  style={{
                    background: colors.background,
                    borderColor: colors.line,
                  }}
                  aria-hidden="true"
                >
                  <i
                    style={{
                      background: colors.panel,
                      borderColor: colors.line,
                    }}
                  />
                  <i style={{ background: colors.accent }} />
                  <i style={{ background: colors.secondary }} />
                </span>
                <span className="tpl-palette-copy">
                  <strong>{preset.name}</strong>
                  <small>{preset.description}</small>
                </span>
                <span className="tpl-palette-check" aria-hidden="true">
                  {palette === key ? "✓" : ""}
                </span>
              </button>
            );
          })}
        </div>
        <div className="tpl-customizer-mode">
          <span>APPEARANCE</span>
          <div className="tpl-customizer-mode-control">
            <span>{mode === "light" ? "Light mode" : "Dark mode"}</span>
            <SkeuoThemeButton
              theme={mode}
              onThemeChange={onModeChange}
              variant="round"
            />
          </div>
        </div>
        <div className="tpl-customizer-footer">
          <button type="button" onClick={onReset}>
            Reset this template
          </button>
          <a href={templatesHref}>All templates ↗</a>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, type ReactNode } from "react";
import { TemplateCustomizer } from "./template-customizer";
import {
  themePresets,
  themeStyle,
  type TemplateMode,
  type TemplatePalette,
} from "./theme-presets";
import "./template-system.css";

export type TemplateOptions = {
  initialPalette?: TemplatePalette;
  initialMode?: TemplateMode;
  templatesHref?: string;
  soundControl?: ReactNode;
  syncPageBackground?: boolean;
};

export type TemplateState = {
  palette: TemplatePalette;
  mode: TemplateMode;
  setMode: (mode: TemplateMode) => void;
  language: "en" | "hi";
  setLanguage: (language: "en" | "hi") => void;
};

export function TemplateFrame({
  id,
  initialPalette = "ember",
  initialMode = "dark",
  syncPageBackground = false,
  templatesHref,
  children,
}: TemplateOptions & {
  id: string;
  children: (state: TemplateState) => ReactNode;
}) {
  const [palette, setPalette] = useState(initialPalette);
  const [mode, setMode] = useState(initialMode);
  const [language, setLanguage] = useState<"en" | "hi">("en");
  const [ready, setReady] = useState(false);
  useEffect(() => {
    let active = true;
    queueMicrotask(() => {
      if (!active) return;
      try {
        const saved = JSON.parse(
          localStorage.getItem(`skeuo-template-v3-${id}`) ?? "null",
        );
        if (saved?.palette && saved.palette in themePresets)
          setPalette(saved.palette);
        if (saved?.mode === "light" || saved?.mode === "dark")
          setMode(saved.mode);
        if (saved?.language === "hi") setLanguage("hi");
      } catch {
        /* Storage is optional for the preview. */
      }
      setReady(true);
    });
    return () => {
      active = false;
    };
  }, [id]);
  useEffect(() => {
    if (!ready) return;
    try {
      localStorage.setItem(
        `skeuo-template-v3-${id}`,
        JSON.stringify({ palette, mode, language }),
      );
    } catch {
      /* Private browsing can disable persistence. */
    }
  }, [id, palette, mode, language, ready]);
  useEffect(() => {
    if (!syncPageBackground) return;
    const html = document.documentElement;
    const body = document.body;
    const previous = [
      html.style.backgroundColor,
      body.style.backgroundColor,
      html.style.colorScheme,
    ];
    html.style.backgroundColor = body.style.backgroundColor =
      themePresets[palette][mode].background;
    html.style.colorScheme = mode;
    return () => {
      [
        html.style.backgroundColor,
        body.style.backgroundColor,
        html.style.colorScheme,
      ] = previous;
    };
  }, [palette, mode, syncPageBackground]);

  return (
    <div
      className={`sk-template sk-template-${id}`}
      data-sk-root=""
      data-theme={mode}
      data-palette={palette}
      style={themeStyle(palette, mode)}
    >
      <a className="sk-t-skip" href="#sk-template-main">
        Skip to content
      </a>
      <TemplateCustomizer
        templatesHref={templatesHref}
        palette={palette}
        mode={mode}
        onPaletteChange={setPalette}
        onModeChange={setMode}
        onReset={() => {
          setPalette(initialPalette);
          setMode(initialMode);
        }}
      />
      {children({ palette, mode, setMode, language, setLanguage })}
    </div>
  );
}

.sk-template {
  background: var(--tpl-bg);
  color: var(--tpl-ink);
  font-family: var(--font-geist-sans), Arial, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  min-height: 100dvh;
  isolation: isolate;
  color-scheme: light;
  --sk-font-sans: var(--font-geist-sans), Arial, sans-serif;
  --sk-surface-raised: var(--tpl-raised);
  --sk-key-base: var(--tpl-well);
  --sk-edge: var(--tpl-line);
  --sk-accent: var(--tpl-accent);
  --sk-accent-ink: var(--tpl-accent-ink);
  --sk-accent-bright: color-mix(in srgb, var(--tpl-accent) 90%, white);
  --sk-accent-base: color-mix(in srgb, var(--tpl-accent) 70%, black);
  --sk-accent-edge: color-mix(in srgb, var(--tpl-accent) 80%, black);
}
.sk-template[data-theme="dark"] {
  color-scheme: dark;
}
.sk-template *,
.sk-template *:before,
.sk-template *:after {
  box-sizing: border-box;
}
.sk-template :is(h1, h2, h3, p, figure, blockquote, dl, dd) {
  margin: 0;
}
.sk-template h1,
.sk-template h2,
.sk-template h3 {
  font-weight: 600;
  letter-spacing: -0.055em;
  line-height: 1.08;
  color: var(--tpl-ink);
}
.sk-template a {
  color: inherit;
  text-decoration: none;
}
.sk-template button,
.sk-template input,
.sk-template select {
  font-family: inherit;
}
.sk-template button,
.sk-template summary,
.sk-template select {
  cursor: pointer;
}
.sk-template button {
  color: inherit;
}
.sk-template a:focus-visible,
.sk-template button:focus-visible,
.sk-template summary:focus-visible,
.sk-template select:focus-visible,
.sk-template [tabindex]:focus-visible {
  outline: 2px solid var(--tpl-accent);
  outline-offset: 5px;
}
.sk-template ::selection {
  background: var(--tpl-accent);
  color: var(--tpl-accent-ink);
}
.sk-template svg {
  display: block;
  max-width: 100%;
}
.sk-template section[id] {
  scroll-margin-top: 32px;
}
.sk-template .sk-t-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.sk-t-skip {
  position: fixed;
  top: 10px;
  left: 10px;
  transform: translateY(-200%);
  z-index: 200;
  background: var(--tpl-accent);
  color: var(--tpl-accent-ink) !important;
  padding: 12px 20px;
  border-radius: 6px;
}
.sk-t-skip:focus {
  transform: none;
}
.sk-t-shell {
  width: min(1320px, calc(100% - 104px));
  margin-inline: auto;
}
.sk-t-section {
  padding-block: 112px;
}
.sk-t-eyebrow {
  font:
    400 10px/1.5 var(--font-geist-mono),
    monospace;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--tpl-muted);
  margin-bottom: 22px !important;
}
.sk-t-eyebrow:before {
  content: "";
  display: inline-block;
  width: 24px;
  height: 1px;
  background: var(--tpl-accent);
  margin: 0 12px 3px 0;
}
.sk-t-brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 27px;
  line-height: 1;
  font-weight: 650;
  letter-spacing: -0.055em;
  white-space: nowrap;
}
.sk-t-brand b {
  color: var(--tpl-accent);
}
.sk-t-brand-symbol {
  width: 31px;
  height: 35px;
  display: grid;
  place-items: center;
  color: var(--tpl-accent);
  flex: none;
}
.sk-t-brand-symbol svg {
  width: 100%;
  height: 100%;
}
.sk-t-brand.is-glide .sk-t-brand-symbol {
  width: 27px;
  height: 27px;
  background: var(--tpl-ink);
  border-radius: 7px;
  color: var(--tpl-bg);
  padding: 5px;
}
.sk-t-icon-button {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  flex: none;
  border: 1px solid var(--tpl-line);
  border-radius: 7px;
  background: var(--tpl-panel);
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 2px 0 var(--tpl-well);
  padding: 0;
}
