  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 25px;
  padding-top: 65px;
  align-items: center;
}
.sk-t-glide-hero h1 {
  font-size: clamp(56px, 6.2vw, 88px);
  max-width: 720px;
  white-space: nowrap;
  letter-spacing: -0.06em;
}
