  color: var(--tpl-accent);
}
.sk-t-glide-object {
  width: 100%;
  margin-top: -30px;
  max-width: 550px;
  aspect-ratio: 1.07;
}
.sk-t-chrome-loop {
  width: 100%;
  height: 100%;
  animation: sk-t-float 8s ease-in-out infinite;
}
.sk-t-glide-principles {
  grid-column: 1/-1;
  display: grid;
  grid-template-columns: 1.1fr 1fr 1fr 1fr;
  border-block: 1px solid var(--tpl-line);
  padding-block: 24px;
  gap: 25px;
  margin-top: 15px;
  font-size: 11px;
  color: var(--tpl-muted);
