.sk-t-glide-heading > p {
  margin-top: 25px;
  color: var(--tpl-muted);
  font-size: 14px;
  line-height: 1.8;
}
.sk-t-feature-rows {
  border-top: 1px solid var(--tpl-line);
}
.sk-t-feature-row {
  display: grid;
  grid-template-columns: 58px 1.1fr 1fr;
  gap: 24px;
