  place-items: center;
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 3px 0 var(--tpl-well);
}
.sk-t-feature-row h3 {
  font-size: 24px;
  margin-bottom: 10px;
}
.sk-t-feature-row p {
  color: var(--tpl-muted);
  font-size: 12px;
  line-height: 1.8;
}
.sk-t-feature-row > p {
  max-width: 390px;
}
.sk-t-bento {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-template-rows: repeat(2, minmax(260px, auto));
  gap: 14px;
}
.sk-t-bento-card {
  position: relative;
  background: var(--tpl-panel);
  border: 1px solid var(--tpl-line);
  border-radius: 16px;
  padding: 30px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 35px;
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 3px 0 var(--tpl-well);
  transition:
    border-color 0.3s,
    transform 0.3s;
}
.sk-t-bento-card:before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(
    340px circle at var(--glow-x, 50%) var(--glow-y, 50%),
    color-mix(in srgb, var(--tpl-accent) 12%, transparent),
    transparent 70%
  );
  transition: opacity 0.3s;
}
.sk-t-bento-card:hover:before {
  opacity: 1;
}
.sk-t-bento-card:hover {
  border-color: color-mix(in srgb, var(--tpl-accent) 50%, var(--tpl-line));
  transform: translateY(-2px);
}
.sk-t-bento-card > * {
  position: relative;
}
.sk-t-bento-card h3 {
  font-size: 25px;
  margin-bottom: 12px;
}
.sk-t-bento-card p {
  color: var(--tpl-muted);
  font-size: 13px;
  line-height: 1.8;
}
