  letter-spacing: 0.12em;
  color: var(--tpl-muted);
}
.sk-t-bento-browser-body > strong {
  display: block;
  font-size: 32px;
  letter-spacing: -0.05em;
  font-weight: 500;
  margin-top: 14px;
}
.sk-t-bento-browser-body > p {
  font-size: 10px;
  margin-top: 5px;
  margin-bottom: 20px;
}
.sk-t-bento-browser-body > div {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 0;
  border-top: 1px solid var(--tpl-line);
