/* Existing Customize control retained. */
.tpl-customizer {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 110;
  color: var(--tpl-ink);
}

.tpl-customizer-trigger {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  min-height: 44px;
  padding: 5px 12px 5px 5px;
  border: 1px solid var(--tpl-line);
  border-radius: 9px;
  color: var(--tpl-ink);
  background: var(--tpl-raised);
  box-shadow:
    inset 0 1px 0 var(--tpl-highlight),
    0 3px 0 var(--tpl-line),
    0 9px 24px var(--tpl-shadow);
  font-size: 12px;
  font-weight: 650;
  cursor: pointer;
}

.tpl-customizer-trigger-art {
  position: relative;
  width: 31px;
  height: 31px;
  display: block;
  background: var(--tpl-well);
  border: 1px solid var(--tpl-line);
  border-radius: 6px;
  box-shadow: inset 0 2px 3px var(--tpl-shadow);
}

.tpl-customizer-trigger-art i {
  position: absolute;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--tpl-accent);
  top: 10px;
  left: 10px;
  box-shadow: 0 1px 0 #0004;
}

.tpl-customizer-trigger-art i:nth-child(2) {
  background: var(--tpl-panel);
  left: 4px;
  top: 4px;
}
.tpl-customizer-trigger-art i:nth-child(3) {
  background: var(--tpl-secondary);
  left: 16px;
  top: 17px;
}

.tpl-customizer-panel {
  position: absolute;
  right: 0;
  bottom: 58px;
  width: min(370px, calc(100vw - 28px));
  max-height: min(650px, calc(100vh - 88px));
  overflow-y: auto;
  padding: 22px;
  border-radius: 13px;
  border: 1px solid var(--tpl-line);
  background: var(--tpl-raised);
  box-shadow:
    inset 0 2px 0 var(--tpl-highlight),
    0 4px 0 var(--tpl-line),
    0 20px 48px var(--tpl-shadow);
}

.tpl-customizer-panel[hidden] {
  display: none;
}
.tpl-customizer-heading {
